const body = $json.body || $json;

let raw_log;
let source_id;

// Si body est une string : Content-Type text/plain → le body EST le log
if (typeof body === "string") {
  raw_log   = body;
  source_id = "unknown";
} else {
  // Content-Type application/json → body a les champs raw_log et source_id
  raw_log   = body.raw_log   ?? null;
  source_id = body.source_id || "unknown";
}

function detectFormat(log) {
  if (!log || typeof log !== "string" || log.trim() === "") return "unknown";

  // JSON : commence par {
  if (log.trimStart().startsWith("{")) return "json";

  // Apache : commence par une IP suivie de "METHOD
  if (/^\d+\.\d+\.\d+\.\d+.*"(GET|POST|PUT|DELETE|PATCH|HEAD|OPTIONS)/.test(log)) return "apache";

  // Syslog : Mois JJ HH:MM:SS hostname process[pid]:
  if (/^[A-Z][a-z]{2}\s+\d{1,2}\s+\d{2}:\d{2}:\d{2}\s+\S+\s+\S+\[/.test(log)) return "syslog";

  // Plaintext : commence par une date YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}/.test(log)) return "plaintext";

  return "unknown";
}

return {
  raw_log,
  source_id,
  format_type: detectFormat(raw_log)
};

const rawStr = $json.raw_log;
const bodySourceId = $json.source_id || "unknown";

let log = {};
try {
  log = typeof rawStr === "string" ? JSON.parse(rawStr) : {};
} catch(e) { log = {}; }

// Préfixer le message avec le level pour que les regex le capturent
const level   = log.level || "";
const message = log.message || JSON.stringify(log);
const fullMessage = level ? `${level}: ${message}` : message;

return {
  source_id:     log.service || log.source_id || bodySourceId,
  log_timestamp: log.timestamp || new Date().toISOString(),
  raw_log:       rawStr,
  message:       fullMessage,
  format_type:   "json"
};

const log = $json.raw_log;

const match = typeof log === "string"
  ? log.match(/^[A-Z][a-z]{2}\s+\d+\s+\d+:\d+:\d+\s+\S+\s+(\S+)\[\d+\]:\s+(.*)$/)
  : null;

return {
  source_id: match?.[1] || $json.source_id || "unknown",
  log_timestamp: new Date().toISOString(),
  raw_log: log,
  message: match?.[2] || log,
  format_type: "syslog"
};

const log = $json.raw_log;

const match = typeof log === "string"
  ? log.match(/(\d+\.\d+\.\d+\.\d+).*?\[(.*?)\]\s+"(.*?)"\s+\d+\s+\d+(.*)/)
  : null;

// match[3] = la requête HTTP  ("POST /api/checkout")
// match[4] = tout ce qui suit (CRITICAL: Database connection pool exhausted)
const requestPart  = match?.[3] || "";
const trailingPart = match?.[4]?.trim() || "";

return {
  source_id:     $json.source_id || "apache",
  log_timestamp: match?.[2] || new Date().toISOString(),
  raw_log:       log,
  message:       trailingPart
                   ? `${requestPart} ${trailingPart}`
                   : (requestPart || log),
  format_type:   "apache"
};

const log = $json.raw_log;

const parts = typeof log === "string" ? log.split(" ") : [];

return {
  source_id: $json.source_id || "unknown",
  log_timestamp: parts.slice(0, 2).join(" ") || new Date().toISOString(),
  raw_log: log,
  message: parts.slice(2).join(" ") || log,
  format_type: "text"
};

return {
  source_id: $json.source_id || "unknown",
  log_timestamp: new Date().toISOString(),
  raw_log: $json.raw_log,
  message: $json.raw_log,
  format_type: "unknown"
};

// WF1 - Code Node: AFD Engine + Regex Evaluation
// Issue #5 | Branch: feat/05-wf1-afd-engine
// LogSentinel - IA-01
//
// $json = output of "AFD State Read" (always 1 row, COALESCE LEFT JOIN)
// $('Insert rows in a table').first().json = log row with id, source_id, message
//
// n8n mode: runOnceForEachItem
// Phase 1 scope: ERROR_CASCADE, RECOVERY, cascade_count not implemented (Issue #13)


// 0. ENV CONFIG
// Requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false in docker-compose (already set).

const TIMEOUT_WINDOW_SEC = parseInt($env.TIMEOUT_WINDOW ?? '300', 10);
const EFFECTIVE_TIMEOUT = Number.isFinite(TIMEOUT_WINDOW_SEC) && TIMEOUT_WINDOW_SEC > 0
  ? TIMEOUT_WINDOW_SEC : 300;


// 1. TRANSITION TABLE delta: Q x Sigma -> Q
// Source: Issue #3, Section 3, 4x6 = 24 entries
// Determinism: 1 output per (state, symbol) pair
// Totality: all 24 entries defined
// Monotonicity: delta(q, sigma_log) >= q except sigma_timeout (resets to INFO)
// Absorption: delta(CRITICAL, sigma) = CRITICAL for all sigma != sigma_timeout

const TRANSITIONS = {
  //           sigma_info    sigma_warn    sigma_error   sigma_crit    sigma_malformed  sigma_timeout
  INFO:     { sigma_info: 'INFO',     sigma_warn: 'WARNING',  sigma_error: 'ERROR',    sigma_crit: 'CRITICAL', sigma_malformed: 'INFO',     sigma_timeout: 'INFO'     },
  WARNING:  { sigma_info: 'INFO',     sigma_warn: 'WARNING',  sigma_error: 'ERROR',    sigma_crit: 'CRITICAL', sigma_malformed: 'WARNING',  sigma_timeout: 'INFO'     },
  ERROR:    { sigma_info: 'WARNING',  sigma_warn: 'WARNING',  sigma_error: 'ERROR',    sigma_crit: 'CRITICAL', sigma_malformed: 'ERROR',    sigma_timeout: 'INFO'     },
  CRITICAL: { sigma_info: 'CRITICAL', sigma_warn: 'CRITICAL', sigma_error: 'CRITICAL', sigma_crit: 'CRITICAL', sigma_malformed: 'CRITICAL', sigma_timeout: 'INFO'     },
};

// Note on delta(ERROR, sigma_info) = WARNING (not INFO):
// Partial recovery - service responds again but we stay in WARNING.
// Only sigma_timeout (prolonged silence) resets fully to INFO.


// 2. REGEX PATTERNS in strict priority order
// Priority: sigma_crit > sigma_error > sigma_warn > sigma_info > sigma_malformed
// First match wins. sigma_malformed is the default (no regex). sigma_timeout is internal.

const REGEX_PATTERNS = [
  {
    symbol: 'sigma_crit',
    // \b prevents partial matches: "uncritical", "non-fatal" won't fire.
    pattern: /\b(CRITICAL|FATAL|EMERGENCY|PANIC|EMERG|KERN_CRIT|SEV1|P1)\b/i,
  },
  {
    symbol: 'sigma_error',
    // HTTP 5xx via 5[0-9]{2}. Common exception class names included.
    // Known false positive (Phase 1): 'GET /error-page 200' -> sigma_error because
    // '/' is a non-word char so \b fires before 'error' in the URL path.
    // Issue #3 Section 5 edge case 1 was wrong on this. Fix in Phase 2 (Issue #4).
    pattern: /\b(ERROR|Exception|Traceback|FAILED|FAILURE|5[0-9]{2}|NullPointer|OutOfMemory|Segfault|SIGSEGV|SIGABRT)\b/i,
  },
  {
    symbol: 'sigma_warn',
    // Negative lookahead TIMEOUT(?!_WINDOW): excludes "TIMEOUT_WINDOW" (internal config param).
    pattern: /\b(WARN|WARNING|SLOW|RETRY|DEPRECATED|TIMEOUT(?!_WINDOW)|HIGH_LATENCY|BACKPRESSURE|THROTTL)\b/i,
  },
  {
    symbol: 'sigma_info',
    // HTTP 2xx via 2[0-9]{2}.
    pattern: /\b(INFO|DEBUG|TRACE|OK|SUCCESS|STARTED|STOPPED|HEALTHY|2[0-9]{2}|CONNECTED|INITIALIZED)\b/i,
  },
  // sigma_malformed: no pattern, default in evaluateSymbol()
  // sigma_timeout: internal temporal signal, never in REGEX_PATTERNS
];


// 3. PURE ENGINE FUNCTIONS

/**
 * evaluateSymbol(message) -> symbol in Sigma
 * null/empty -> sigma_malformed before any regex. First match wins.
 */
function evaluateSymbol(message) {
  if (message === null || message === undefined) return 'sigma_malformed';
  if (typeof message !== 'string' || message.trim() === '') return 'sigma_malformed';
  for (const { symbol, pattern } of REGEX_PATTERNS) {
    if (pattern.test(message)) return symbol;
  }
  return 'sigma_malformed';
}

/**
 * applyTransition(currentState, symbol) -> newState
 * Unknown state falls back to INFO. Unknown symbol leaves state unchanged.
 */
function applyTransition(currentState, symbol) {
  const row = TRANSITIONS[currentState];
  if (!row) return TRANSITIONS['INFO'][symbol] ?? 'INFO';
  return row[symbol] ?? currentState;
}


// 4. READ LOG DATA from the Insert node (carries id, source_id, message, etc.)
const logObject = $('Insert rows in a table').first().json;
const sourceId  = logObject.source_id ?? 'unknown';
const message   = logObject.message   ?? '';
const now       = new Date();


// 5. READ CURRENT AFD STATE from $json (= "AFD State Read" output)
// "AFD State Read" uses COALESCE with a LEFT JOIN so it always returns exactly 1 row.
// New service: current_state = 'INFO', last_event_time = null
const stateRow = $json;

let currentState  = 'INFO';
let lastEventTime = now;
let isNewService  = true;

if (stateRow?.current_state) {
  // Normalize legacy 'NOMINAL' (schema.sql default from Phase 0) -> 'INFO' (Phase 1 q0)
  currentState = (stateRow.current_state === 'NOMINAL') ? 'INFO' : stateRow.current_state;
  if (!TRANSITIONS[currentState]) currentState = 'INFO';

  if (stateRow.last_event_time) {
    lastEventTime = new Date(stateRow.last_event_time);
    isNewService  = false;
    // last_event_time is null for new services (COALESCE returned INFO but no real row)
  }
}


// 6. TEMPORAL RESET (sigma_timeout)
// If no log received for TIMEOUT_WINDOW seconds: apply delta(q, sigma_timeout) first,
// then delta(result, sigma_log). New services skip this (no last_event_time to compare).

const elapsedMs  = now - lastEventTime;
const elapsedSec = elapsedMs / 1000;

let stateAfterTimeout = currentState;
let timeoutApplied    = false;

if (!isNewService && elapsedSec > EFFECTIVE_TIMEOUT) {
  stateAfterTimeout = applyTransition(currentState, 'sigma_timeout');
  timeoutApplied    = true;
}


// 7. SYMBOL EVALUATION AND TRANSITION

const symbol        = evaluateSymbol(message);
const newState      = applyTransition(stateAfterTimeout, symbol);
const previousState = currentState; // state before any transition (audit trail)


// 8. RETURN ENRICHED OBJECT
// "AFD State Write" node (after this) runs:
//   INSERT INTO afd_states ... ON CONFLICT DO UPDATE using $json.afd_state etc.
// "Log State Write" node (after this) runs:
//   UPDATE logs SET afd_state, afd_symbol, previous_state WHERE id = $json.id

return {
  ...logObject,           // all fields from Insert node (including id)
  afd_symbol:      symbol,
  afd_state:       newState,
  previous_state:  previousState,
  source_id:       sourceId,
  is_new_service:  isNewService,
  timeout_applied: timeoutApplied,
  elapsed_sec:     Math.round(elapsedSec),
  timeout_window:  EFFECTIVE_TIMEOUT,
  engine_ts:       now.toISOString(),
  // Not in Phase 1: cascade_count, cascade_start_time, ERROR_CASCADE, RECOVERY (Issue #13)
};

const originalLog = $('AFD Engine').first().json;
const rows = $input.all();
const recent_logs = rows.map(r => r.json.message);

return [{
  json: {
    ...originalLog,
    recent_logs
  }
}];

const log = $input.first().json;

const actions = Array.isArray(log.actions_immediates)
  ? log.actions_immediates
  : [];

const timestamp = new Date().toISOString();

/**
 * Format all actions
 */
const actionsText = actions.length
  ? actions.map((a, i) => `${i + 1}. ${a}`).join('\n')
  : "N/A";

/**
 * WhatsApp Message 
 */
const whatsappMessage = `
CRITICAL — ${log.source_id}

${log.message?.slice(0, 200)}

Cause probable:
${log.cause_probable}

Actions:
${actionsText}

${timestamp}

Reply:
ACK — Prise en charge
FALSE POSITIVE — Faux positif
CORRIGER WARNING — Reclassifier warning
CORRIGER ERROR — Reclassifier error
RESOLVED — Incident résolu
STATUS — État du système
ESCALATE — Escalader
HELP — Aide
`;

/**
 * HTML Email (no emojis)
 */
const htmlMessage = `
<h2>CRITICAL Alert</h2>

<p><b>Service:</b> ${log.source_id}</p>

<p><b>Message:</b><br>${log.message}</p>

<p><b>Cause probable:</b><br>${log.cause_probable}</p>

<p><b>Actions:</b></p>
<ul>
${actions.map(a => `<li>${a}</li>`).join('')}
</ul>

<p><b>Timestamp:</b> ${timestamp}</p>
`;

return [
  {
    json: {
      ...log,
      whatsappMessage,
      htmlMessage,
      alert_timestamp: timestamp
    }
  }
];

