// 1. Get WhatsApp data directly from the Webhook node
// Replace 'WhatsApp Feedback Webhook' with the exact name of your webhook node
const webhookData = $('WhatsApp Feedback Webhook').item.json;
const body = webhookData.body?.Body?.trim()?.toUpperCase() || "";
const from = webhookData.body?.From;

// 2. Get context data from the Postgres node (the current input)
const source_id = $json.source_id || null;
const afd_state = $json.afd_state || null;
const message = $json.message || null;

let result = {
  type: "UNKNOWN",
  new_state: afd_state,
  raw: body,
  from: from,
  source_id: source_id,
  afd_state: afd_state,
  message: message
};

// 3. Command Logic
// 3. Improved Command Logic using .startsWith()
if (body.startsWith("ACK")) {
    result.type = "ACK";
} 
else if (body.startsWith("FALSE POSITIVE")) {
    result.type = "FALSE_POSITIVE";
} 
else if (body.startsWith("CORRIGER WARNING")) {
    result.type = "CORRIGER";
    result.new_state = "WARNING";
} 
else if (body.startsWith("CORRIGER ERROR")) {
    result.type = "CORRIGER";
    result.new_state = "ERROR";
} 
else if (body.startsWith("RESOLVED")) {
    result.type = "RESOLVED";
} 
else if (body.startsWith("STATUS")) {
    result.type = "STATUS";
} 
else if (body.startsWith("ESCALATE")) {
    result.type = "ESCALATE";
} 
else if (body.startsWith("HELP")) {
    result.type = "HELP";
}

return [{ json: result }];

